import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"DA-1255 / DA-E16-13 — Duplicate Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/duplicate-workspace/spec.md","filePath":"feature/agency-workspace/duplicate-workspace/spec.md"}'),s={name:"feature/agency-workspace/duplicate-workspace/spec.md"};function c(i,e,n,p,l,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="da-1255-da-e16-13-—-duplicate-workspace" tabindex="-1">DA-1255 / DA-E16-13 — Duplicate Workspace <a class="header-anchor" href="#da-1255-da-e16-13-—-duplicate-workspace" aria-label="Permalink to &quot;DA-1255 / DA-E16-13 — Duplicate Workspace&quot;">​</a></h1><p>Agency Owner creates a new Workspace from one in the same Agency for a new Campaign. The Owner supplies a new name and independently selects whether to copy the source timezone and which active Manager, Creator and Client memberships to copy.</p><ul><li>The current Owner is always a Manager in the new Workspace unless another selected Manager replaces them; at most one Manager may be active.</li><li>The Owner reviews member identities and roles before submitting. Only selected, currently valid members are copied. A Client retains a link to the same ClientProfile, not a copy of the profile; no invitation is recreated.</li><li><code>copyTimezone=false</code> uses the Workspace default <code>Asia/Ho_Chi_Minh</code>; true copies only the effective timezone from canonical <code>timezone_config</code>, which Workspace API exposes as <code>settings.timezone</code> (consistency fix 2026-10-14, superseding JSON-first precedence). The other <code>settings</code> keys, profile/branding fields, logo/banner and files are not copied.</li><li>Workspace resources are not copied in this release because the resource management module is not implemented. The UI must not offer a functional resource-copy switch.</li><li>The new Workspace has its own ID and lifecycle. It never inherits selected/approved Package, Campaign, Task, approval, chat, invitation, social token or execution history. Existing Package selection/approval is required before its Campaign can be created.</li><li>Only the Owner of the source Agency may duplicate it; deleted sources are rejected. The source never changes. Retrying with the same request ID returns the same new Workspace, without creating another one. Failures roll back the entire copy.</li></ul><p>API: <code>POST /api/v1/workspaces/{workspaceId}/duplicate</code>, request <code>{requestId, name, copyTimezone, memberIds}</code>; response 201 with Workspace data.</p><p>This feature is distinct from DA-E16-12 Save Workspace Template, which stores a reusable configuration and does not create a Workspace with selected members.</p>',5)])])}const m=a(s,[["render",c]]);export{u as __pageData,m as default};
